def generate(seed):
    r = random.Random(seed)
    bits = format(r.randrange(256), '08b')
    out = []
    for _ in range(r.randint(4, 6)):
        L = r.randint(10, 14)
        a = ''.join(r.choice('01') for _ in range(L))
        b = ''.join(bits[7 - int(a[i - 1] + a[i] + a[(i + 1) % L], 2)] for i in range(L))
        out.append(a + '>' + b)
    return ' '.join(out)

