def solve(clue):
    P = [q.split('>') for q in clue.split()]
    for n in range(256):
        bits = format(n, '08b')
        ok = True
        for a, b in P:
            L = len(a)
            if ''.join(bits[7 - int(a[i - 1] + a[i] + a[(i + 1) % L], 2)] for i in range(L)) != b:
                ok = False
                break
        if ok:
            return bits
    return ''

